; RawScaleF4 ($2DAD2)
; Called from: Reset, FreezeFrameCapture, FuelSysConditions, FuelSysConditions2, CamSensorMonitor, ReadAnalogInputs, RawScaleChain, ReadMap
;---------------------------------------------------------------------------------------------------
RawScaleF4:
        LDAB    $7000
        MUL
        ADDD    $7001
        BCC     L2DAE2
        LDD     #$FFFF
L2DAE2:
        RTS

;---------------------------------------------------------------------------------------------------
; HighRpmTimerPit ($2DAE4)
; Called from: Isr_PIT
;---------------------------------------------------------------------------------------------------
HighRpmTimerPit:
        BRCLR   >CrankFlags2,Z,#$80,L2DB26               ; bit 7: reference event seen since the last PIT check (Isr_GPT_IC1, HighRpmTimerPit)
        BRSET   >CrankFlags2,Z,#$40,L2DB26               ; bit 6: EngineRpm reached $1900 (HighRpmTimerPit)
        LDD     >EngineRpm,Z
        CPD     #$1900
        BCS     L2DB1E
        BSET    >CrankFlags2,Z,#$40                      ; bit 6: EngineRpm reached $1900 (HighRpmTimerPit)
        LDD     >HighRpmTimer,Z
        CPD     #$0E39
        BCS     L2DB0E
        LDD     #$FFFF
        BRA     L2DB14
L2DB0E:
        LDE     #$0012
        EMUL
L2DB14:
        STD     >HighRpmTimer,Z
        BCLR    >CrankFlags2,Z,#$02                      ; bit 1: engine rpm below $1900: HighRpmTimer counting (HighRpmTimerPit); AsdRelayCheck and others read it
        BRA     L2DB26
L2DB1E:
        INCW    >HighRpmTimer,Z
        BSET    >CrankFlags2,Z,#$02                      ; bit 1: engine rpm below $1900: HighRpmTimer counting (HighRpmTimerPit); AsdRelayCheck and others read it
L2DB26:
        RTS

;---------------------------------------------------------------------------------------------------
; HighRpmTimerUpdate ($2DB28)
; Called from: EquipmentInit
;---------------------------------------------------------------------------------------------------
HighRpmTimerUpdate:
        BRCLR   >CrankFlags2,Z,#$20,L2DB34               ; bit 5: vehicle speed or bus speed value high (Isr_GPT_IC3); HighRpmTimerUpdate counts
        INCW    >HighRpmTimer,Z
        BRA     L2DB4E
L2DB34:
        BRCLR   >CrankFlags2,Z,#$10,L2DB4E               ; bit 4: timer update due for HighRpmTimer (HighRpmTimerUpdate)
        LDD     >HighRpmTimer,Z
        LSRD
        LSRD
        ADDD    >HighRpmTimer,Z
        STD     >HighRpmTimer,Z
        BCLR    >CrankFlags2,Z,#$10                      ; bit 4: timer update due for HighRpmTimer (HighRpmTimerUpdate)
L2DB4E:
        BRCLR   >CrankFlags2,Z,#$08,L2DB5A               ; bit 3: VSS period long ($07D0 or more) not seen (Isr_GPT_IC3); HighRpmTimerUpdate counts HighRpmTimer2
        INCW    >HighRpmTimer2,Z
        BRA     L2DB74
L2DB5A:
        BRCLR   >CrankFlags2,Z,#$04,L2DB74               ; bit 2: timer update due for HighRpmTimer2 (HighRpmTimerUpdate)
        LDD     >HighRpmTimer2,Z
        LSRD
        LSRD
        ADDD    >HighRpmTimer2,Z
        STD     >HighRpmTimer2,Z
        BCLR    >CrankFlags2,Z,#$04                      ; bit 2: timer update due for HighRpmTimer2 (HighRpmTimerUpdate)
L2DB74:
        RTS

;---------------------------------------------------------------------------------------------------
; MonSteadyRateCalc ($2DB76)
; Called from: EquipmentInit
;---------------------------------------------------------------------------------------------------
MonSteadyRateCalc:
        LDE     >EngineRpm,Z
        LDD     >MonSteadyAB8,Z
        SDE
        TED
        ASRD
        ASRD
        ADE
        STE     >MonSteadyRate,Z
        LDE     >EngineRpm,Z
        STE     >MonSteadyAB8,Z
        RTS

;---------------------------------------------------------------------------------------------------
; Sub_2DB96 ($2DB96)
; Called from: Isr_GPT_IC1
;---------------------------------------------------------------------------------------------------
Sub_2DB96:
        LDAA    >PORTF0,Z
        ANDA    #$1F
        ORAA    #$20
        STAA    >PORTF0,Z
        LDAB    #$20
        STAB    >ADCTL1_L,Z
        RTS

;---------------------------------------------------------------------------------------------------
; AdcStartF0 ($2DBAA)
; Called from: Isr_GPT_IC1
;---------------------------------------------------------------------------------------------------
AdcStartF0:
        LDAA    >PORTF0,Z
        ANDA    #$1F
        ORAA    #$20
        STAA    >PORTF0,Z
        LDAB    #$30
        STAB    >ADCTL1_L,Z
        RTS

;---------------------------------------------------------------------------------------------------
; ReadMap ($2DBBE)
; Called from: Isr_GPT_IC1
;---------------------------------------------------------------------------------------------------
ReadMap:
        BRCLR   >ControlFlags943,Z,#$04,L2DC48           ; bit 2: output toggled by EgrOutputTest, not read
        TST     $0402,Z
        BNE     L2DC48
L2DBCA:
        BRCLR   >ADCSTAT_L,Z,#$01,L2DBCA                 ; bit 0: CCF0: ADC conversion 0 complete
        LDAA    >RJURR0_L,Z
        STAA    >MapRaw,Z
        LDAB    $0DD8,Z
        CMPB    <Baro,Z
        BHI     L2DC02
        LDAB    >EngineRpm,Z
        CMPB    #$6E
        BCC     L2DC02
        CMPB    #$13
        BCS     L2DC02
        LDAB    >ThrottleAboveClosed,Z
        CMPB    >MapRationalThrottleMax
        BCC     L2DC02
        CMPA    >MapRawHighLimit
        BCC     L2DC08
        CMPA    >MapRawLowLimit
        BCS     L2DC08
L2DC02:
        BRCLR   >SensorFaultFlags,Z,#$20,L2DC0E          ; bit 5: MAP sensor fault (P0106, P0107, P0108 or P1297 set): limp MAP in use
L2DC08:
        JSR     LimpMapCalc
        BRA     L2DC1A
L2DC0E:
        LDAB    >MapRawStart,Z
        ABA
        RORA
        JSR     RawScaleF4
L2DC1A:
        BRCLR   >Options0337,#$08,L2DC2C                 ; bit 3: selects a branch in ReadMap
        TAB
        ADDA    >ReadMapA81,Z
        RORA
        STAB    >ReadMapA81,Z
L2DC2C:
        STAA    >Map,Z
        JSR     RawScale69
        STAA    >ReadMapA82,Z
        LDAB    >Map,Z
        LDAA    <Baro,Z
        SBA
        BCC     L2DC44
        CLRA
L2DC44:
        STAA    >ManifoldVacuum,Z
L2DC48:
        RTS

;---------------------------------------------------------------------------------------------------
; EquipmentDetect ($2DC4A)
; Called from: EquipmentInit
;---------------------------------------------------------------------------------------------------
EquipmentDetect:
        BRSET   >EquipmentFlags,Z,#$80,L2DCA4            ; bit 7: A/C fitted (EquipmentDetect)
        BRCLR   >Options0331,#$80,L2DC66                 ; bit 7: A/C pressure sensor fitted, not a switch (AcPressureSensor): idle A/C steps, clutch, cut and fan
        LDAA    >AcSensorRaw,Z
        CMPA    >AcSensorRawHigh
        BHI     L2DC66
        CMPA    >AcSensorRawLow
        BHI     L2DC8A
L2DC66:
        BRSET   >Options0331,#$40,L2DC82                 ; bit 6: A/C detection variant (EquipmentDetect, AcClutchControl, FanRelayControl)
        BRCLR   >Options0331,#$20,L2DC7A                 ; bit 5: A/C detection variant (EquipmentDetect, AcClutchControl)
        BRCLR   >SwitchInputs2,Z,#$80,L2DCA0             ; bit 7: A/C request switch (AcClutchControl, EquipmentDetect)
        BRA     L2DC8A
L2DC7A:
        BRSET   >SwitchInputs2,Z,#$80,L2DCA0             ; bit 7: A/C request switch (AcClutchControl, EquipmentDetect)
        BRA     L2DC8A
L2DC82:
        BRCLR   >AcFlags,Z,#$08,L2DCA0                   ; bit 3: A/C request from the bus (message bit 0 in CcdReceive)
        BRA     L2DC9C
L2DC8A:
        LDAA    >AcPresentCounter,Z
        CMPA    >AcPresentCount
        BCC     L2DC9C
        INCA
        STAA    >AcPresentCounter,Z
        BRA     L2DCA4
L2DC9C:
        BSET    <EquipmentFlags,Z,#$80                   ; bit 7: A/C fitted (EquipmentDetect)
L2DCA0:
        CLR     >AcPresentCounter,Z
L2DCA4:
        BRSET   >EquipmentFlags,Z,#$40,L2DCF6            ; bit 6: speed control fitted (EquipmentDetect, EquipmentProbe)
        BRCLR   >Options032D,#$20,L2DCC8                 ; bit 5: A/C clutch logic on (AcClutchLogicOn); also selects the switch-input map, the VSS constants and the speed control lamp
        BRCLR   >SwitchInputs2,Z,#$10,L2DCC8             ; bit 4: speed control on/off switch (speed control code, lamp state, EquipmentDetect)
        LDAA    >SpeedCtlPresentCounter,Z
        CMPA    >SpeedCtlPresentCount
        BCC     L2DCF2
        INCA
        STAA    >SpeedCtlPresentCounter,Z
        BRA     L2DCCC
L2DCC8:
        CLR     >SpeedCtlPresentCounter,Z
L2DCCC:
        BRSET   >SwitchInputs2,Z,#$08,L2DCF2             ; bit 3: speed control switch
        BRCLR   >SwitchInputs2,Z,#$04,L2DCF2             ; bit 2: speed control switch (set at reset)
        BRCLR   >Options0332,#$02,L2DCE6                 ; bit 1: speed control switch variant; also used by EquipmentDetect
        BRSET   >SwitchInputs2,Z,#$10,L2DCF2             ; bit 4: speed control on/off switch (speed control code, lamp state, EquipmentDetect)
        BRA     L2DCF6
L2DCE6:
        BRCLR   >Options0332,#$04,L2DCF6                 ; bit 2: speed control switch variant; also used by EquipmentDetect
        BRCLR   >SwitchInputs2,Z,#$11,L2DCF6             ; bit 4: speed control on/off switch (speed control code, lamp state, EquipmentDetect); bit 0: speed control switch
L2DCF2:
        BSET    <EquipmentFlags,Z,#$40                   ; bit 6: speed control fitted (EquipmentDetect, EquipmentProbe)
L2DCF6:
        BRSET   >EquipmentFlags,Z,#$04,L2DD30            ; bit 2: power steering pressure switch fitted (calibration bit $0331.3, or EquipmentDetect)
        BRCLR   >EngineStateFlags,Z,#$80,L2DD2C          ; bit 7: engine turning: set at the first reference pulse, cleared when the engine stalls (CalcEngineRpm)
        BRSET   >IoInputs0,Z,#$08,L2DD2C                 ; bit 3: key off, probably: the monitors skip while it is set and CheckPowerDown starts the power-down path
        LDAA    >BatteryVolts2,Z
        CMPA    #$C2
        BCS     L2DD2C
        BRSET   >SwitchInputs2,Z,#$40,L2DD2C             ; bit 6: power steering pressure switch: P0551 in PspSwitchMonitor, idle air and idle rpm adders (with EquipmentFlags bit 2)
        LDAA    >PspPresentCounter,Z
        CMPA    >PspPresentCount
        BCC     L2DD28
        INCA
        STAA    >PspPresentCounter,Z
        BRA     L2DD30
L2DD28:
        BSET    <EquipmentFlags,Z,#$04                   ; bit 2: power steering pressure switch fitted (calibration bit $0331.3, or EquipmentDetect)
L2DD2C:
        CLR     >PspPresentCounter,Z
L2DD30:
        RTS

;---------------------------------------------------------------------------------------------------
; EquipmentProbe ($2DD32)
; Called from: CheckPowerDown
;---------------------------------------------------------------------------------------------------
EquipmentProbe:
        BRSET   >EquipmentFlags,Z,#$40,L2DD74            ; bit 6: speed control fitted (EquipmentDetect, EquipmentProbe)
        LDAA    >TFLG1,Z
        BITA    #$05
        BNE     L2DD74
        LDX     #$FF0C
        JSR     PowerInputHold
        BCS     L2DD74
        LDX     #$FF0C
        JSR     PowerInputHold
        BCS     L2DD74
        BSETW   >IoCtl12,Z,#$0080
        LDX     #$7F86
        JSR     PowerInputHold
        BCS     L2DD6E
        BRCLR   >IoCtl12,Z,#$01,L2DD6E
        BSET    <EquipmentFlags,Z,#$40                   ; bit 6: speed control fitted (EquipmentDetect, EquipmentProbe)
L2DD6E:
        BCLRW   >IoCtl12,Z,#$0080
L2DD74:
        RTS

;---------------------------------------------------------------------------------------------------
; CatTempInput ($2DD76)
; Called from: Reset, CatTempMonitor
;---------------------------------------------------------------------------------------------------
CatTempInput:
        CLRB
        TBXK
        LDX     #CatTempSensorCurve
        LDAA    >FlexSensorRaw,Z
        STAA    >CatTempInputRaw,Z
        JSR     Lookup2D
        TST     >CatTempFiltered,Z
        BEQ     L2DD9A
        CLRA
        ADDB    >CatTempFiltered,Z
        ADCA    #$00
        LSRD
L2DD9A:
        STAB    >CatTempFiltered,Z
        CLRA
        LDE     #$0113
        ADE
        ASLE
        STE     >CatTempA65,Z
        TBA
        RTS

;---------------------------------------------------------------------------------------------------
; CatTempMonitor ($2DDB0)
; Called from: EquipmentInit
;---------------------------------------------------------------------------------------------------
CatTempMonitor:
        BRCLR   >Options0330,#$10,L2DE60                 ; bit 4: catalyst temperature sensor fitted (CatTempMonitor; sets EquipmentFlags bit 0)
        JSR     CatTempInput
        BRSET   >FaultSet1A,Z,#$08,L2DE60
        BRSET   >FaultSet1A,Z,#$10,L2DE60
        BRCLR   >EngineStateFlags,Z,#$80,L2DE58          ; bit 7: engine turning: set at the first reference pulse, cleared when the engine stalls (CalcEngineRpm)
        LDD     >Count3s,Z
        CPD     #$031D
        LBCS    L2DE58
        LDAA    >Count3s,Z
        CMPA    >CatTempCheckTime
        BCS     L2DE12
        LDY     #$4E87
        LDAA    >CatTempInputRaw,Z
        CMPA    >CatTempSensorHigh
        BCC     L2DDFA
        LDY     #$4E91
        CMPA    >CatTempSensorLow
        BHI     L2DE1C
L2DDFA:
        LDAA    >CatTempFaultCounter,Z
        ADDA    #$01
        SBCA    #$00
        STAA    >CatTempFaultCounter,Z
        CMPA    >CatTempFaultCount
        BCS     L2DE60
        JSR     ReportFault
        BRA     L2DE58
L2DE12:
        LDAA    >CatTempInputRaw,Z
        CMPA    >CatTempSensorLow
        BLS     L2DE58
L2DE1C:
        LDAA    >CatTempFiltered,Z
        CMPA    >CatTempOverheatOff
        BLS     L2DE58
        BRSET   >CatTemp6B1,Z,#$01,L2DE36
        CMPA    >CatTempOverheat
        BCS     L2DE58
        BSET    >CatTemp6B1,Z,#$01
L2DE36:
        BRSET   >FaultSet19,Z,#$08,L2DE60
        LDAA    >CatTempFaultCounter,Z
        ADDA    #$01
        SBCA    #$00
        STAA    >CatTempFaultCounter,Z
        CMPA    >CatTempFaultCount
        BCS     L2DE60
        LDY     #$4D97
        JSR     ReportFault
        BRA     L2DE5C
L2DE58:
        BCLR    >CatTemp6B1,Z,#$01
L2DE5C:
        CLR     >CatTempFaultCounter,Z
L2DE60:
        RTS
